// Map each editor lesson → the short_id it is (or will be) persisted under.
// A lesson's short_id must be STABLE across reorders/renames: it's the key that
// ties lesson_progress rows and calendar events to the lesson. We therefore
// derive it from the lesson's identity, NOT from its position or `number`:
//   • a lesson loaded from the DB carries its authoritative `persistedShortId`
//     (including random refs generated by duplicate_course) — reuse it verbatim.
//   • a newly authored lesson has a stable random suffix. Numeric allocation
//     remains for older drafts/seeds which already used that convention.
// The old scheme (`${courseShortId}-${lesson.number}`) renumbered short_ids
// whenever `number`/position drifted, orphaning progress rows → lessons the
// teacher had opened showed up locked in the student track.
const generatedLessonId = /^lesson-[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/i

export function newEditorLessonId(): string {
  return `lesson-${crypto.randomUUID()}`
}

export function lessonShortIdMap(courseShortId: string, lessons: Array<{ id: string; persistedShortId?: string }>): Record<string, string> {
  const prefix = `${courseShortId}-`
  const map: Record<string, string> = {}
  let maxN = -1
  for (const l of lessons) {
    const persisted = l.persistedShortId ?? l.id
    if (l.persistedShortId) map[l.id] = persisted
    else if (generatedLessonId.test(l.id)) map[l.id] = prefix + l.id
    if (persisted.startsWith(prefix)) {
      const suffix = persisted.slice(prefix.length)
      if (generatedLessonId.test(suffix)) map[l.id] = persisted
      if (/^\d+$/.test(suffix)) { map[l.id] = persisted; maxN = Math.max(maxN, Number(suffix)) }
    }
  }
  for (const l of lessons) {
    if (!map[l.id]) { maxN += 1; map[l.id] = `${prefix}${maxN}` }
  }
  return map
}

